{
  "id": 52,
  "knowledge": "Risk Zone Category",
  "description": "Classification system that evaluates archaeological sites for degradation risk based on preservation status and structural condition.",
  "definition": "Categorizes archaeological sites into two main groups: 'Degradation Risk Zone' and 'Not in Risk Zone'. 'Not in Risk Zone' means that the site is not in a Degradation Risk Zone."
}

{
  "id": 16,
  "knowledge": "Digital Conservation Priority",
  "description": "Classification system for prioritizing digital conservation efforts based on site conditions, historical significance, and preservation status.",
  "definition": "A scoring system where sites in Degradation Risk Zones with \\text{Estimated Date} older than 1000 BCE or with \\text{Site Type} = 'Rare' or 'Unique' receive highest priority for digital preservation through Premium Quality Scans, requiring immediate allocation of scanning resources."
}

{
  "id": 50,
  "knowledge": "Environmental Condition Classification System (ECCS)",
  "description": "A comprehensive classification system for archaeological site environments based on their suitability for scanning operations.",
  "definition": "A four-tier classification where 'Optimal Scanning Conditions' have \\text{ESI} > 85, 'Good Scanning Conditions' have ESI between 70-85, 'Acceptable Scanning Conditions' have ESI between 50-70, and 'Challenging Scanning Conditions' have ESI < 50. This classification guides scanning schedule planning and equipment selection to maximize data quality."
}

{
  "id": 35,
  "knowledge": "Conservation Priority Index (CPI)",
  "description": "Quantifies the urgency of conservation efforts based on site condition, historical significance and structural stability.",
  "definition": "CPI = \\begin{cases} 100 - PS + AF \\times \\left(1 + \\frac{TS}{10}\\right), & \\text{if in a Degradation Risk Zone} \\\\ 50 - PS + AF \\times \\left(1 + \\frac{TS}{20}\\right), & \\text{otherwise} \\end{cases}, \\text{ where PS is 0-100 based on \\text{Preservation Status} condition ('Excellent'=10, 'Good'=30, 'Fair'=50, 'Poor'=70, 'Critical'=90), AF is approximate age in millennia derived from \\text{Estimated Date}, and TS is 0-10 based on \\text{Site Type} rarity.}"
}
